    /**
     * Parse the rule identified by {@code ruleId} starting at {@code offset}
     * in {@code input}. Unlike {@link #parse(String)}, the matched rule is
     * not required to consume all remaining input — parsing stops when the
     * rule itself finishes, and the returned {@link PartialParse#endOffset()}
     * reports the absolute offset at which it stopped.
     *
     * @since 0.3.0
     */
    public Result<PartialParse> parseRuleAt(
            Class<? extends RuleId> ruleId,
            String input, int offset) {
        if (ruleId == null) {
            return Result.failure(new ParseError(SourceLocation.START, "Rule id class is null"));
        }
        if (input == null) {
            return Result.failure(new ParseError(SourceLocation.START, "Input is null"));
        }
        if (offset < 0 || offset > input.length()) {
            return Result.failure(new ParseError(SourceLocation.START,
                    "Offset " + offset + " out of range [0, " + input.length() + "]"));
        }
        var supplier = ruleDispatch.get(ruleId);
        if (supplier == null) {
            return Result.failure(new ParseError(SourceLocation.START,
                    "Unknown rule for class " + ruleId.getSimpleName()));
        }
        init(input);
        seekTo(offset);
        var result = supplier.get();
        if (result.isFailure()) {
            var errorLoc = furthestFailure.or(location());
            var expected = furthestExpected.filter(s -> !s.isEmpty()).or(result.expected.or("valid input"));
            return Result.failure(new ParseError(errorLoc, "expected " + expected));
        }
        return Result.success(new PartialParse(result.node.unwrap(), pos));
    }

    /**
     * Seek the parsing context to {@code offset}, computing
     * {@code line}/{@code column} from the prefix. Shared by
     * {@link #parseRuleAt(Class, String, int)}.
     */
    private void seekTo(int offset) {
        this.pos = 0;
        this.line = 1;
        this.column = 1;
        for (int i = 0; i < offset; i++) {
            if (input.charAt(i) == '\n') {
                line++;
                column = 1;
            } else {
                column++;
            }
        }
        this.pos = offset;
    }

    // === Rule Parsing Methods ===

    private CstParseResult parse_Input() {
        int startOffset = pos;
        int startLine = line;
        int startColumn = column;
        
        // Check cache at pre-whitespace position. Bug B fix:
        // on a settled-success cache hit we must reproduce the first-parse
        // trivia attribution — drain pending-leading, run skipWhitespace at
        // the same pre-WS position, then jump pos to the cached body-end and
        // attach the rebuilt leading trivia. Failure hits return as-is.
        long key = cacheKey(0, startOffset);
        if (cache != null) {
            var cached = cache.get(key);
            if (cached != null) {
                if (cached.isSuccess()) {
                    var hitCarriedLeading = takePendingLeading();
                    var hitLocalLeading = (tokenBoundaryDepth > 0) ? List.<Trivia>of() : skipWhitespace();
                    var hitLeading = concatTrivia(hitCarriedLeading, hitLocalLeading);
                    var hitEndLoc = cached.endLocation.unwrap();
                    restoreLocation(hitEndLoc);
                    var hitNode = attachLeadingTrivia(cached.node.unwrap(), hitLeading);
                    return CstParseResult.success(hitNode, cached.text.or(""), hitEndLoc);
                }
                return cached;
            }
        }
        
        // Skip leading whitespace and combine with carried pending-leading.
        var carriedLeading = takePendingLeading();
        var localLeadingTrivia = (tokenBoundaryDepth > 0) ? List.<Trivia>of() : skipWhitespace();
        var leadingTrivia = concatTrivia(carriedLeading, localLeadingTrivia);
        var children = new ArrayList<CstNode>();
        var __ruleName = RULE_INPUT;
        
        CstParseResult result = CstParseResult.successNoLoc(null, "");
        int seqStartPos0 = pos;
        int seqStartLine0 = line;
        int seqStartColumn0 = column;
        int seqPending0 = savePendingLeading();
        var seqChildren0 = new ArrayList<>(children);
        result = parse_Input_seq0_chunk0(children, seqStartPos0, seqStartLine0, seqStartColumn0, seqPending0, seqChildren0);
        if (result.isSuccess()) result = parse_Input_seq0_chunk1(children, seqStartPos0, seqStartLine0, seqStartColumn0, seqPending0, seqChildren0);
        if (result.isSuccess()) {
            result = CstParseResult.successNoLoc(null, substring(seqStartPos0, pos));
        }
        
        CstParseResult finalResult;
        CstParseResult cacheableResult;
        if (result.isSuccess()) {
            var endLoc = location();
            var span = new SourceSpan(startLine, startColumn, startOffset, endLoc.line(), endLoc.column(), endLoc.offset());
            var pendingAtExit = takePendingLeading();
            var cacheNode = wrapWithRuleName(result, children, span, RULE_INPUT, List.<Trivia>of());
            var node = wrapWithRuleName(result, children, span, RULE_INPUT, leadingTrivia);
            if (!pendingAtExit.isEmpty()) {
                cacheNode = attachTrailingToTail(cacheNode, pendingAtExit);
                node = attachTrailingToTail(node, pendingAtExit);
            }
            cacheableResult = CstParseResult.success(cacheNode, result.text.or(""), endLoc);
            finalResult = CstParseResult.success(node, result.text.or(""), endLoc);
        } else {
            this.pos = startOffset;
            this.line = startLine;
            this.column = startColumn;
            if (!carriedLeading.isEmpty()) pendingLeadingTrivia.addAll(carriedLeading);
            finalResult = result;
            cacheableResult = finalResult;
        }
        
        if (cache != null) cache.put(key, cacheableResult);
        return finalResult;
    }

